begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated,service_role;
select no_plan();
-- All identities and legal references below are synthetic test fixtures only.
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('a2400000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','dsr-all240-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)select('a2400000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'COMPLIANCE_MANAGER'from generate_series(1,2)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2400000-0000-4000-8000-000000000001','TEST DSR240','TEST DSR240','ACTIVE','a2400000-0000-4000-8000-000000000001'),('b2400000-0000-4000-8000-000000000002','TEST foreign240','TEST foreign240','ACTIVE','a2400000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)values('c2400000-0000-4000-8000-000000000001','b2400000-0000-4000-8000-000000000001','a2400000-0000-4000-8000-000000000003','REVOKED');
insert into public.data_subject_requests(id,organization_id,request_type,subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,correlation_id,created_by)values('d2400000-0000-4000-8000-000000000001','b2400000-0000-4000-8000-000000000001','ACCESS',encode(extensions.digest(convert_to('b2400000-0000-4000-8000-000000000001:a2400000-0000-4000-8000-000000000003','UTF8'),'sha256'),'hex'),'ENHANCED','fr-MA','IN_REVIEW',now()+interval'1 day',now()-interval'1 day',extensions.gen_random_uuid(),'a2400000-0000-4000-8000-000000000001');
create table public.dsr_all_subject_fixture240(id uuid primary key,organization_id uuid references public.organizations(id),subject_user_id uuid references auth.users(id),created_by uuid references auth.users(id),personal_text text,quantity numeric,api_secret text);
alter table public.dsr_all_subject_fixture240 enable row level security;
insert into public.dsr_all_subject_fixture240 values('f2400000-0000-4000-8000-000000000001','b2400000-0000-4000-8000-000000000001','a2400000-0000-4000-8000-000000000003','a2400000-0000-4000-8000-000000000004','TEST own exact record',9007199254740993,'TEST_SECRET_SENTINEL'),('f2400000-0000-4000-8000-000000000002','b2400000-0000-4000-8000-000000000002','a2400000-0000-4000-8000-000000000003','a2400000-0000-4000-8000-000000000003','TEST foreign organization',1,'TEST_SECRET_SENTINEL'),('f2400000-0000-4000-8000-000000000003','b2400000-0000-4000-8000-000000000001','a2400000-0000-4000-8000-000000000004','a2400000-0000-4000-8000-000000000003','TEST another subject authored by this user',1,'TEST_SECRET_SENTINEL');
insert into public.credit_wallets(id,organization_id,wallet_type)values('c2401000-0000-4000-8000-000000000001','b2400000-0000-4000-8000-000000000001','CLIENT'),('c2401000-0000-4000-8000-000000000002','b2400000-0000-4000-8000-000000000002','CLIENT');
insert into public.credit_ledger_entries(organization_id,wallet_id,entry_type,quantity,idempotency_scope,idempotency_key,correlation_id,reference_type,reference_id,created_by)values
 ('b2400000-0000-4000-8000-000000000001','c2401000-0000-4000-8000-000000000001','GRANT',9007199254740993,'fixture.dsr240','subject-own-240',extensions.gen_random_uuid(),'TEST','OWN_240','a2400000-0000-4000-8000-000000000003'),
 ('b2400000-0000-4000-8000-000000000001','c2401000-0000-4000-8000-000000000001','GRANT',2,'fixture.dsr240','same-org-other-240',extensions.gen_random_uuid(),'TEST','OTHER_PERSON_240','a2400000-0000-4000-8000-000000000001'),
 ('b2400000-0000-4000-8000-000000000002','c2401000-0000-4000-8000-000000000002','GRANT',3,'fixture.dsr240','other-org-subject-240',extensions.gen_random_uuid(),'TEST','OTHER_TENANT_240','a2400000-0000-4000-8000-000000000003');
create temporary table dsr240(k text primary key,v jsonb);grant all on dsr240 to authenticated;
select ok(private.dsr_all_column_exportable_v1('public','question_bank_questions','question_key','text'),'known question business identifier is exportable');
select ok(not private.dsr_all_column_security_secret_v1('public','question_bank_questions','question_key','text'),'question identifier is never mislabelled as an authentication credential');
select ok(not private.dsr_all_column_exportable_v1('auth','users','encrypted_password','text'),'password hashes cannot be included by an inventory');
select ok(not private.dsr_all_column_exportable_v1('auth','mfa_factors','secret','text'),'TOTP seeds cannot be included by an inventory');
select ok(not private.dsr_all_column_exportable_v1('private','refresh_hmac_keys','key','text'),'private refresh keys cannot be included by an inventory');
select is(private.dsr_all_redact_security_json_v1('public','questionnaire_answers','{"question_key":"Q_TEST","access_token":"TEST_SECRET_SENTINEL","nested":{"password":"TEST_SECRET_SENTINEL","value":"safe"}}'),' {"question_key":"Q_TEST","nested":{"value":"safe"}}'::jsonb,'structured answers retain their known identifiers while secret keys are removed recursively');
select is(private.dsr_all_disclosure_remove_path_v1('{"profile":{"own":"Subject","other":"Third party"}}','/profile/other'),'{"profile":{"own":"Subject"}}'::jsonb,'selective object redaction preserves the subject portion');
select is(private.dsr_all_disclosure_remove_path_v1('{"a/b":{"~value":"remove","keep":"safe"}}','/a~1b/~0value'),'{"a/b":{"keep":"safe"}}'::jsonb,'object redaction decodes escaped property names without changing siblings');
select throws_ok($$select private.dsr_all_disclosure_remove_path_v1('{"profile":["Subject","Third party"]}','/profile/0')$$,'22023','DSR_JSON_ARRAY_REQUIRES_WHOLE_FIELD_REVIEW','array-index redactions are refused instead of shifting later targets');
select throws_ok($$select private.dsr_all_disclosure_path_v1('/profile/~2invalid')$$,'22023','INVALID_DSR_DISCLOSURE_PATH','invalid pointer escapes cannot target a different property');
set local role authenticated;select set_config('request.jwt.claim.sub','a2400000-0000-4000-8000-000000000003',true);select set_config('request.jwt.claims','{"sub":"a2400000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
insert into dsr240 values('scope',public.confirm_my_dsr_scope_v1('d2400000-0000-4000-8000-000000000001',array['ALL'],'TEST-240-scope'));
select throws_ok($$select public.create_dsr_all_inventory_draft_v1('TEST unauthorized inventory attempt','TEST-240-denied')$$,'42501','DSR_LEGAL_STAFF_REQUIRED','a verified subject cannot become the inventory authority');
select set_config('request.jwt.claim.sub','a2400000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a2400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into dsr240 values('draft',public.create_dsr_all_inventory_draft_v1('TEST synthetic disclosure classifications only, never a production legal approval','TEST-240-draft'));
reset role;
select ok((select(v->>'source_count')::integer>500 from dsr240 where k='draft'),'technical inventory covers the deployed Auth/public/private/Storage catalogue');
create function pg_temp.classify_all240()returns void language plpgsql as $$
declare source jsonb;fields jsonb;excluded jsonb;config_value jsonb;begin
 for source in select value from public.dsr_all_inventory_drafts_v1,jsonb_array_elements(catalog_json)where id=(select(v->>'draft_id')::uuid from dsr240 where k='draft')loop
  fields:='[]';
  if source->>'key'in('public.dsr_all_subject_fixture240','@subject_financial_records_v1')then select jsonb_agg(c->>'name')into fields from jsonb_array_elements(source->'columns')c where(c->>'exportable')::boolean;end if;
  select coalesce(jsonb_object_agg(c->>'name',jsonb_build_object('basis_code',case when(c->>'security_secret')::boolean then'SECURITY_SECRET'else'NOT_PERSONAL_DATA'end,'legal_reference','TEST-ONLY-240-SYNTHETIC-DISCLOSURE','reason','TEST fixture policy for isolated synthetic records, not a real legal approval')),'{}')into excluded from jsonb_array_elements(source->'columns')c where not fields?(c->>'name');
  config_value:=jsonb_build_object('mode',case when source->>'key'in('public.dsr_all_subject_fixture240','@subject_financial_records_v1')then'EXTRACT'else'EXCLUDE'end,'subject_path_id',case when source->>'key'in('public.dsr_all_subject_fixture240','@subject_financial_records_v1')then source#>>'{subject_paths,0,id}'end,'organization_path_ids',case when source->>'key'in('public.dsr_all_subject_fixture240','@subject_financial_records_v1')then jsonb_build_array(source#>>'{organization_paths,0,id}')else'[]'::jsonb end,'account_global',false,'include_null_organization',false,'fields',fields,'excluded_fields',excluded,'legal_reference','TEST-ONLY-240-SYNTHETIC-DISCLOSURE','reason','TEST fixture policy for isolated synthetic records, not a real legal approval');
  perform public.configure_dsr_all_inventory_source_v1((select(v->>'draft_id')::uuid from dsr240 where k='draft'),source->>'key',0,config_value,'TEST-240-classify:'||(source->>'key'));
 end loop;
end$$;
set local role authenticated;
select throws_ok($$select public.submit_dsr_all_inventory_v1((select(v->>'draft_id')::uuid from dsr240 where k='draft'),(select v->>'catalog_hash'from dsr240 where k='draft'),'TEST-240-LEGAL-REFERENCE','TEST-240-empty-submit')$$,'55000','DSR_INVENTORY_UNCLASSIFIED_SOURCE','ALL cannot skip an unclassified technical source');
reset role;
select pg_temp.classify_all240();
set local role authenticated;
insert into dsr240 values('version',public.submit_dsr_all_inventory_v1((select(v->>'draft_id')::uuid from dsr240 where k='draft'),(select v->>'catalog_hash'from dsr240 where k='draft'),'TEST-240-LEGAL-REFERENCE','TEST-240-submit'));
select throws_ok($$select public.decide_dsr_all_inventory_v1((select(v->>'inventory_version_id')::uuid from dsr240 where k='version'),(select v->>'content_hash'from dsr240 where k='version'),true,true,'TEST-240-LEGAL-REFERENCE','TEST self approval denied')$$,'42501','DSR_INVENTORY_INDEPENDENT_REVIEW_REQUIRED','the inventory author cannot approve their classifications');
select set_config('request.jwt.claim.sub','a2400000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a2400000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.decide_dsr_all_inventory_v1((select(v->>'inventory_version_id')::uuid from dsr240 where k='version'),(select v->>'content_hash'from dsr240 where k='version'),true,false,'TEST-240-LEGAL-REFERENCE','TEST explicit review must be confirmed')$$,'22023','DSR_DOCUMENTED_LEGAL_REVIEW_REQUIRED','independent approval requires explicit review confirmation');
select public.decide_dsr_all_inventory_v1((select(v->>'inventory_version_id')::uuid from dsr240 where k='version'),(select v->>'content_hash'from dsr240 where k='version'),true,true,'TEST-240-LEGAL-REFERENCE','TEST independent synthetic policy review, no real legal approval');
insert into dsr240 values('capture',public.capture_admin_dsr_all_v1('d2400000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from dsr240 where k='scope'),(select(v->>'inventory_version_id')::uuid from dsr240 where k='version'),'TEST-240-capture'));
insert into dsr240 values('replay',public.capture_admin_dsr_all_v1('d2400000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from dsr240 where k='scope'),(select(v->>'inventory_version_id')::uuid from dsr240 where k='version'),'TEST-240-capture'));
reset role;
select is((select v->>'package_id'from dsr240 where k='capture'),(select v->>'package_id'from dsr240 where k='replay'),'capture retry returns the original immutable cut');
insert into dsr240 select'snapshot',snapshot_json::jsonb from public.dsr_all_packages_v1 where id=(select(v->>'package_id')::uuid from dsr240 where k='capture');
select is((select(s->>'record_count')::integer from dsr240,jsonb_array_elements(v->'sources')s where k='snapshot'and s->>'source_key'='public.dsr_all_subject_fixture240'),1,'only the actual subject in the requested organization is extracted');
select is((select s#>>'{records,0,fields,quantity}'from dsr240,jsonb_array_elements(v->'sources')s where k='snapshot'and s->>'source_key'='public.dsr_all_subject_fixture240'),'9007199254740993','large decimal values survive exactly as text');
select is((select s#>>'{records,0,fields,created_by}'from dsr240,jsonb_array_elements(v->'sources')s where k='snapshot'and s->>'source_key'='public.dsr_all_subject_fixture240'),null::text,'another actor identifier is redacted even inside a subject-owned row');
select is((select position('TEST_SECRET_SENTINEL'in snapshot_json)from public.dsr_all_packages_v1 where id=(select(v->>'package_id')::uuid from dsr240 where k='capture')),0,'the protected capture never stores the nonexportable secret field');
select is((select(s->>'record_count')::integer from dsr240,jsonb_array_elements(v->'sources')s where k='snapshot'and s->>'source_key'='@subject_financial_records_v1'),1,'the explicitly classified curated financial source includes only personally authored records in the DSR organization');
select is((select s#>>'{records,0,fields,quantity}'from dsr240,jsonb_array_elements(v->'sources')s where k='snapshot'and s->>'source_key'='@subject_financial_records_v1'),'9007199254740993','each curated financial record remains individually reviewable with exact amounts');
select ok((select not coalesce((v#>>'{file_sources,coverage_complete}')::boolean,false)from dsr240 where k='snapshot'),'unconfigured external processing never becomes a complete file coverage');
select is((select count(*)from public.event_outbox where event_type='DsrAllCapturedV1'and aggregate_id=(select v->>'package_id'from dsr240 where k='capture')),1::bigint,'capture retry emits one durable fact and no duplicate effect');
set local role authenticated;select set_config('request.jwt.claim.sub','a2400000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a2400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into dsr240 select'cut',public.propose_admin_dsr_all_exclusion_v1((select(v->>'package_id')::uuid from dsr240 where k='capture'),(select v->>'source_sha256'from dsr240 where k='capture'),'public.dsr_all_subject_fixture240',s->>'source_hash',array['personal_text'],'{}','THIRD_PARTY_RIGHTS','TEST-240-EXCLUSION-REFERENCE','TEST synthetic field exclusion; no real legal approval','TEST-240-cut')from dsr240,jsonb_array_elements(v->'sources')s where k='snapshot'and s->>'source_key'='public.dsr_all_subject_fixture240';
select throws_ok($$select public.decide_admin_dsr_all_exclusion_v1((select(v->>'proposal_id')::uuid from dsr240 where k='cut'),(select v->>'content_hash'from dsr240 where k='cut'),true,true,'TEST-240-REVIEW-REFERENCE','TEST self review must be rejected')$$,'42501','DSR_EXCLUSION_INDEPENDENT_REVIEW_REQUIRED','a preparer cannot approve their own content exclusion');
select set_config('request.jwt.claim.sub','a2400000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a2400000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select public.decide_admin_dsr_all_exclusion_v1((select(v->>'proposal_id')::uuid from dsr240 where k='cut'),(select v->>'content_hash'from dsr240 where k='cut'),true,true,'TEST-240-REVIEW-REFERENCE','TEST independent field review; no real legal approval');
reset role;
insert into dsr240 values('files',private.dsr_all_file_manifest_v1((select(v->>'package_id')::uuid from dsr240 where k='capture')));
set local role authenticated;select set_config('request.jwt.claim.sub','a2400000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a2400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into dsr240 values('response',public.prepare_admin_dsr_all_response_v1((select(v->>'package_id')::uuid from dsr240 where k='capture'),(select v->>'source_sha256'from dsr240 where k='capture'),(select v->>'manifest_hash'from dsr240 where k='files'),'TEST-240-response'));
reset role;
insert into dsr240 select'response-document',response_json::jsonb from public.dsr_private_responses_v1 where id=(select(v->>'response_id')::uuid from dsr240 where k='response');
select ok(not exists(select 1 from dsr240,jsonb_array_elements(v->'sources')s where k='response-document'and s->>'source_key'='public.dsr_all_subject_fixture240'and(s#>'{records,0,fields}')?'personal_text'),'a reviewed exclusion actually removes the selected field from the disclosed copy');
select ok(exists(select 1 from dsr240,jsonb_array_elements(v->'sources')s where k='snapshot'and s->>'source_key'='public.dsr_all_subject_fixture240'and(s#>'{records,0,fields}')?'personal_text'),'the original source cut remains intact for controlled proof');
select is((select(v->>'complete')::boolean from dsr240 where k='response'),false,'real file helpers do not turn an unconfigured controller or external processing into complete ALL');
select ok(not exists(select 1 from dsr240 where k='response-document'and(v?'file_sources')),'the delivered copy never includes the staff-only raw Storage candidate list');
select*from finish();rollback;
